def transform(grid):
    from collections import Counter, deque
    R, C = len(grid), len(grid[0])
    colors = Counter(v for row in grid for v in row)
    divider = None
    for c in colors:
        if any(all(grid[i][j] == c for j in range(C)) for i in range(R)) or \
           any(all(grid[i][j] == c for i in range(R)) for j in range(C)):
            divider = c
            break
    bg = max((c for c in colors if c != divider), key=lambda c: colors[c])
    marker = 8
    rows = [i for i in range(R) if all(grid[i][j] == divider for j in range(C))]
    cols = [j for j in range(C) if all(grid[i][j] == divider for i in range(R))]
    def segments(n, divs):
        segs, start = [], 0
        for d in divs:
            if d > start:
                segs.append((start, d))
            start = d + 1
        if start < n:
            segs.append((start, n))
        return segs
    out = []
    for r0, r1 in segments(R, rows):
        row = []
        for c0, c1 in segments(C, cols):
            cells = {(i, j) for i in range(r0, r1) for j in range(c0, c1) if grid[i][j] == marker}
            n = 0
            while cells:
                n += 1
                start = cells.pop()
                q = deque([start])
                while q:
                    i, j = q.popleft()
                    for di in (-1, 0, 1):
                        for dj in (-1, 0, 1):
                            if (i + di, j + dj) in cells:
                                cells.remove((i + di, j + dj))
                                q.append((i + di, j + dj))
            row.append(n if n > 0 else bg)
        out.append(row)
    return out
